UPDATE `quest_template_locale` SET `Title` = NULL, `Details` = '$b        Введите эту строку в чат, чтобы узнать ваш прогресс:$b$b        /run print(C_QuestLog.IsQuestFlaggedCompleted(1461))', `VerifiedBuild` = 0 WHERE `locale` = 'ruRU' AND `ID` = 1461;
