UPDATE `quest_template_locale` SET `Details` = 'Отнесите осколок зеленого скипетра Анахроносу в Пещеры Времени в Танарисе.', `VerifiedBuild` = 0 WHERE `locale` = 'ruRU' AND `ID` = 8741;
